/* Keep a hidden Tools tab from leaving its author controls selected. */
exports.name="forge-reader-sidebar";
exports.platforms=["browser"];
exports.after=["startup"];
exports.synchronous=true;
exports.startup=function(){
 var mode="$:/temp/HUWiki/AuthorReadingMode", tab="$:/state/tab/sidebar--595412856";
 function update(){
  if($tw.wiki.getTiddlerText(mode)==="reading" &&
    $tw.wiki.getTiddlerText(tab,$tw.wiki.getTiddlerText("$:/config/DefaultSidebarTab"))==="$:/core/ui/SideBar/Tools"){
   $tw.wiki.addTiddler({title:tab,text:"$:/core/ui/SideBar/Open"});
  }
 }
 update();
 $tw.wiki.addEventListener("change",function(changes){if(changes[mode]||changes[tab])update();});
};
